-- FAQ de Teclab, tanda 3 (28/11/2026): Inbound Marketing (224), Experiencia del Cliente (225),
-- Gestión Hotelera (231), Eventos (232) y Periodismo (233) de 3 a 9. Textos aprobados por el usuario.
-- Fuentes: fichas oficiales de teclab.edu.ar, plan y títulos en D1, certificados en conocimiento/teclab.md,
-- carreras/teclab/articulaciones-teclab.json; nombres de Siglo 21 verificados en 21.edu.ar.
-- conocimiento/teclab.md da otros títulos para Inbound («Marketing Entrante (Inbound Marketing)») y
-- CX («Experiencia del Cliente (Customer Experiencia)»): confirmar contra la resolución.
-- Cada UPDATE exige el JSON y el título actuales: si alguno cambió, no escribe.
UPDATE carreras SET slides = '[{"type":"faq","items":[{"pregunta":"¿Qué se aprende en la Tecnicatura en Inbound Marketing?","respuesta":"Estudiás atracción y conversión de clientes, contenidos, gestión de marca y planificación de estrategias de Inbound Marketing. La propuesta incluye automatización, CRM y métricas para acompañar la relación con los clientes."},{"pregunta":"¿Cuál es la diferencia entre Inbound Marketing y Marketing Digital?","respuesta":"Marketing Digital abarca estrategias y acciones en distintos canales digitales. Inbound Marketing pone el foco en atraer personas con contenido útil, convertir ese interés en consultas y acompañar la relación hasta la fidelización del cliente."},{"pregunta":"¿Para qué sirven los contenidos y el CRM en Inbound Marketing?","respuesta":"Los contenidos ayudan a atraer audiencias interesadas y responder sus dudas. El CRM organiza la información y el seguimiento de los contactos, mientras la automatización permite acompañar distintas etapas de la relación con el cliente."},{"pregunta":"¿Cuánto dura la tecnicatura y cómo se cursa?","respuesta":"Dura 2 años, organizados en cuatro cuatrimestres. Se cursa 100% online, con clases en vivo que quedan grabadas y prácticas aplicadas."},{"pregunta":"¿Qué título obtengo al terminar?","respuesta":"El de Técnico Superior en Inbound Marketing, un título oficial con acreditación nacional. El plan contempla además el certificado intermedio de Asistente en Inbound Marketing."},{"pregunta":"¿Necesito conocimientos previos?","respuesta":"No. La carrera arranca desde cero, con análisis de inbound marketing, estrategias de marketing digital y gestión de marca en el primer cuatrimestre."},{"pregunta":"¿Tiene salida laboral?","respuesta":"Sí. Podés trabajar en áreas de marketing digital, como community manager, especialista en inbound o en gestión de CRM, o como consultor."},{"pregunta":"¿Tiene prácticas?","respuesta":"Sí. En el último cuatrimestre hacés Práctica profesional I y II, donde aplicás lo aprendido a situaciones de trabajo."},{"pregunta":"¿Puedo seguir estudiando en Universidad Siglo 21 después?","respuesta":"Sí. El título articula con la Licenciatura en Publicidad y con la Licenciatura en Marketing y Comercialización de Universidad Siglo 21. Podés ver qué materias se reconocen en el simulador de equivalencias de Siglo 21."}]}]' WHERE id = 224 AND titulo = 'Técnico Superior en Inbound Marketing' AND slides = '[{"type":"faq","items":[{"pregunta":"¿Qué se aprende en la Tecnicatura en Inbound Marketing?","respuesta":"Estudiás atracción y conversión de clientes, contenidos, gestión de marca y planificación de estrategias de Inbound Marketing. La propuesta incluye automatización, CRM y métricas para acompañar la relación con los clientes."},{"pregunta":"¿Cuál es la diferencia entre Inbound Marketing y Marketing Digital?","respuesta":"Marketing Digital abarca estrategias y acciones en distintos canales digitales. Inbound Marketing pone el foco en atraer personas con contenido útil, convertir ese interés en consultas y acompañar la relación hasta la fidelización del cliente."},{"pregunta":"¿Para qué sirven los contenidos y el CRM en Inbound Marketing?","respuesta":"Los contenidos ayudan a atraer audiencias interesadas y responder sus dudas. El CRM organiza la información y el seguimiento de los contactos, mientras la automatización permite acompañar distintas etapas de la relación con el cliente."}]}]';
UPDATE carreras SET slides = '[{"type":"faq","items":[{"pregunta":"¿Qué se aprende en Experiencia del Cliente o Customer Experience?","respuesta":"Estudiás análisis de la experiencia del cliente, diseño de servicios, gestión de marca y planificación de CX. La formación se orienta a mejorar los puntos de contacto entre las personas y una organización."},{"pregunta":"¿Qué hace un técnico en Experiencia del Cliente?","respuesta":"Analiza cómo se relacionan los clientes con una empresa, detecta dificultades en ese recorrido y propone mejoras en la atención y los servicios. También participa en estrategias de satisfacción, retención y fidelización."},{"pregunta":"¿La carrera de Customer Experience incluye experiencia de usuario?","respuesta":"Sí. El plan incluye Experiencia de Usuario y contenidos de diseño del servicio al cliente. La formación integra esas herramientas con la gestión de la relación entre la organización y sus clientes en distintos puntos de contacto."},{"pregunta":"¿Cuánto dura la tecnicatura y cómo se cursa?","respuesta":"Dura 2 años, organizados en cuatro cuatrimestres. Se cursa 100% online, con clases en vivo que quedan grabadas y prácticas aplicadas."},{"pregunta":"¿Qué título obtengo al terminar?","respuesta":"El de Técnico Superior en Customer Experience, un título oficial con acreditación nacional. El plan contempla además el certificado intermedio de Asistente en Customer Experience."},{"pregunta":"¿Necesito conocimientos previos?","respuesta":"No. La carrera arranca desde cero, con el análisis y las bases operativas de la experiencia del cliente en el primer cuatrimestre."},{"pregunta":"¿Tiene salida laboral?","respuesta":"Sí. Podés trabajar en empresas de servicios, comercio electrónico, centros de contacto y áreas de atención al cliente, customer success y gestión de clientes."},{"pregunta":"¿Tiene prácticas?","respuesta":"Sí. En el último cuatrimestre hacés Práctica profesional I y II, donde aplicás lo aprendido a situaciones de trabajo."},{"pregunta":"¿Puedo seguir estudiando en Universidad Siglo 21 después?","respuesta":"Sí. El título articula con la Licenciatura en Marketing y Comercialización de Universidad Siglo 21. Podés ver qué materias se reconocen en el simulador de equivalencias de Siglo 21."}]}]' WHERE id = 225 AND titulo = 'Técnico Superior en Customer Experience' AND slides = '[{"type":"faq","items":[{"pregunta":"¿Qué se aprende en Experiencia del Cliente o Customer Experience?","respuesta":"Estudiás análisis de la experiencia del cliente, diseño de servicios, gestión de marca y planificación de CX. La formación se orienta a mejorar los puntos de contacto entre las personas y una organización."},{"pregunta":"¿Qué hace un técnico en Experiencia del Cliente?","respuesta":"Analiza cómo se relacionan los clientes con una empresa, detecta dificultades en ese recorrido y propone mejoras en la atención y los servicios. También participa en estrategias de satisfacción, retención y fidelización."},{"pregunta":"¿La carrera de Customer Experience incluye experiencia de usuario?","respuesta":"Sí. El plan incluye Experiencia de Usuario y contenidos de diseño del servicio al cliente. La formación integra esas herramientas con la gestión de la relación entre la organización y sus clientes en distintos puntos de contacto."}]}]';
UPDATE carreras SET slides = '[{"type":"faq","items":[{"pregunta":"¿Qué se aprende en la Tecnicatura en Gestión Hotelera?","respuesta":"Estudiás reservas y recepción, housekeeping, alimentos y bebidas, eventos y experiencia del huésped. La formación también incluye presupuestos, comercialización y revenue management para administrar servicios hoteleros."},{"pregunta":"¿Qué hace un técnico en Gestión Hotelera?","respuesta":"Participa en la coordinación de reservas, recepción, servicios y equipos de un establecimiento. También puede colaborar en la organización de eventos y en el control de la calidad de la experiencia del huésped."},{"pregunta":"¿Gestión Hotelera incluye administración y comercialización?","respuesta":"Sí. Además de las operaciones del hotel, el plan aborda gestión de presupuestos, proyectos, comercialización y revenue management. Son herramientas para analizar ingresos, tarifas y recursos del negocio hotelero."},{"pregunta":"¿Cuánto dura la tecnicatura y cómo se cursa?","respuesta":"Dura 2 años, organizados en cuatro cuatrimestres. Se cursa 100% online, con clases en vivo que quedan grabadas y prácticas aplicadas."},{"pregunta":"¿Qué título obtengo al terminar?","respuesta":"El de Técnico Superior en Gestión Hotelera, un título oficial con acreditación nacional. El plan contempla además el certificado intermedio de Asistente de Operación en Hoteles."},{"pregunta":"¿Necesito conocimientos previos?","respuesta":"No. La carrera arranca desde cero, con gestión de reservas y front desk y housekeeping en el primer cuatrimestre."},{"pregunta":"¿Tiene salida laboral?","respuesta":"Sí. Podés trabajar en hoteles, turismo, agencias de viajes, eventos, catering y empresas de hospitalidad."},{"pregunta":"¿Tiene prácticas?","respuesta":"Sí. En el último cuatrimestre hacés Práctica profesional I y II, donde aplicás lo aprendido a situaciones de trabajo."},{"pregunta":"¿Puedo seguir estudiando en Universidad Siglo 21 después?","respuesta":"Sí. El título articula con la Licenciatura en Administración Hotelera de Universidad Siglo 21. Podés ver qué materias se reconocen en el simulador de equivalencias de Siglo 21."}]}]' WHERE id = 231 AND titulo = 'Técnico Superior en Gestión Hotelera' AND slides = '[{"type":"faq","items":[{"pregunta":"¿Qué se aprende en la Tecnicatura en Gestión Hotelera?","respuesta":"Estudiás reservas y recepción, housekeeping, alimentos y bebidas, eventos y experiencia del huésped. La formación también incluye presupuestos, comercialización y revenue management para administrar servicios hoteleros."},{"pregunta":"¿Qué hace un técnico en Gestión Hotelera?","respuesta":"Participa en la coordinación de reservas, recepción, servicios y equipos de un establecimiento. También puede colaborar en la organización de eventos y en el control de la calidad de la experiencia del huésped."},{"pregunta":"¿Gestión Hotelera incluye administración y comercialización?","respuesta":"Sí. Además de las operaciones del hotel, el plan aborda gestión de presupuestos, proyectos, comercialización y revenue management. Son herramientas para analizar ingresos, tarifas y recursos del negocio hotelero."}]}]';
UPDATE carreras SET slides = '[{"type":"faq","items":[{"pregunta":"¿Qué se aprende en Planificación y Organización de Eventos?","respuesta":"Estudiás diseño y planificación de eventos, presupuestos, alimentos y bebidas, ceremonial y protocolo. La formación también incluye comunicación, tecnología y gestión de proyectos para coordinar recursos y proveedores."},{"pregunta":"¿Qué hace un organizador de eventos?","respuesta":"Define la propuesta, organiza el presupuesto y coordina equipos, proveedores y tiempos. Durante la realización del evento, acompaña la logística y la ejecución de lo planificado según los objetivos de cada proyecto."},{"pregunta":"¿Cuál es la salida laboral de Organización de Eventos?","respuesta":"La formación se aplica en agencias, empresas, instituciones y centros de convenciones. Permite participar en eventos sociales y corporativos, gestionar logística y proveedores o desarrollar servicios de organización de manera independiente."},{"pregunta":"¿Cuánto dura la tecnicatura y cómo se cursa?","respuesta":"Dura 2 años, organizados en cuatro cuatrimestres. Se cursa 100% online, con clases en vivo que quedan grabadas y prácticas aplicadas."},{"pregunta":"¿Qué título obtengo al terminar?","respuesta":"El de Técnico Superior en Planificación y Organización de Eventos, un título oficial con acreditación nacional. El plan contempla además el certificado intermedio de Asistente de Organización de Eventos."},{"pregunta":"¿Necesito conocimientos previos?","respuesta":"No. La carrera arranca desde cero, con diseño de eventos y planificación de eventos en el primer cuatrimestre."},{"pregunta":"¿Puedo trabajar en eventos antes de terminar?","respuesta":"Sí. A medida que avanzás podés sumarte como asistente de producción, coordinador junior o en tareas de logística para agencias o productoras; depende de lo que pida cada lugar."},{"pregunta":"¿Tiene prácticas?","respuesta":"Sí. En el último cuatrimestre hacés Práctica profesional I y II, donde aplicás lo aprendido a situaciones de trabajo."},{"pregunta":"¿Puedo seguir estudiando en Universidad Siglo 21 después?","respuesta":"Sí. El título articula con la Licenciatura en Relaciones Públicas e Institucionales de Universidad Siglo 21. Podés ver qué materias se reconocen en el simulador de equivalencias de Siglo 21."}]}]' WHERE id = 232 AND titulo = 'Técnico Superior en Planificación y Organización de Eventos' AND slides = '[{"type":"faq","items":[{"pregunta":"¿Qué se aprende en Planificación y Organización de Eventos?","respuesta":"Estudiás diseño y planificación de eventos, presupuestos, alimentos y bebidas, ceremonial y protocolo. La formación también incluye comunicación, tecnología y gestión de proyectos para coordinar recursos y proveedores."},{"pregunta":"¿Qué hace un organizador de eventos?","respuesta":"Define la propuesta, organiza el presupuesto y coordina equipos, proveedores y tiempos. Durante la realización del evento, acompaña la logística y la ejecución de lo planificado según los objetivos de cada proyecto."},{"pregunta":"¿Cuál es la salida laboral de Organización de Eventos?","respuesta":"La formación se aplica en agencias, empresas, instituciones y centros de convenciones. Permite participar en eventos sociales y corporativos, gestionar logística y proveedores o desarrollar servicios de organización de manera independiente."}]}]';
UPDATE carreras SET slides = '[{"type":"faq","items":[{"pregunta":"¿Qué se aprende en Periodismo y Nuevas Tecnologías?","respuesta":"Estudiás producción de noticias, redacción digital, redes sociales, multimedios y periodismo de datos. La formación combina investigación y comunicación con herramientas para crear contenidos en nuevos formatos."},{"pregunta":"¿La carrera de Periodismo incluye formatos digitales y multimedia?","respuesta":"Sí. La propuesta aborda noticias para plataformas digitales, redes sociales y producción multimedia. Incluye trabajo con formatos como podcast, radio digital y video, además del análisis de datos para producir información periodística."},{"pregunta":"¿Cuál es la salida laboral de Periodismo y Nuevas Tecnologías?","respuesta":"La formación se vincula con medios, redacciones, áreas de prensa, agencias de contenidos y proyectos de comunicación digital. Permite participar en redacción multimedia, producción audiovisual y gestión de contenidos para redes sociales."},{"pregunta":"¿Cuánto dura la tecnicatura y cómo se cursa?","respuesta":"Dura 2 años, organizados en cuatro cuatrimestres. Se cursa 100% online, con clases en vivo que quedan grabadas y prácticas aplicadas."},{"pregunta":"¿Qué título obtengo al terminar?","respuesta":"El de Técnico Superior en Periodismo y Nuevas Tecnologías, un título oficial con acreditación nacional. El plan contempla además el certificado intermedio de Asistente Junior en Periodismo."},{"pregunta":"¿Necesito conocimientos previos?","respuesta":"No. La carrera arranca desde cero, con producción de noticias y redacción periodística en la era digital en el primer cuatrimestre."},{"pregunta":"¿Puedo trabajar en comunicación digital antes de terminar?","respuesta":"Sí. A medida que avanzás podés postularte a puestos iniciales de redacción, community management o producción de contenidos; depende de lo que pida cada lugar."},{"pregunta":"¿Tiene prácticas?","respuesta":"Sí. En el último cuatrimestre hacés Práctica profesional I y II, donde aplicás lo aprendido a situaciones de trabajo."},{"pregunta":"¿Puedo seguir estudiando en Universidad Siglo 21 después?","respuesta":"Sí. El título articula con la Licenciatura en Periodismo de Universidad Siglo 21. Podés ver qué materias se reconocen en el simulador de equivalencias de Siglo 21."}]}]' WHERE id = 233 AND titulo = 'Técnico Superior en Periodismo y Nuevas Tecnologías' AND slides = '[{"type":"faq","items":[{"pregunta":"¿Qué se aprende en Periodismo y Nuevas Tecnologías?","respuesta":"Estudiás producción de noticias, redacción digital, redes sociales, multimedios y periodismo de datos. La formación combina investigación y comunicación con herramientas para crear contenidos en nuevos formatos."},{"pregunta":"¿La carrera de Periodismo incluye formatos digitales y multimedia?","respuesta":"Sí. La propuesta aborda noticias para plataformas digitales, redes sociales y producción multimedia. Incluye trabajo con formatos como podcast, radio digital y video, además del análisis de datos para producir información periodística."},{"pregunta":"¿Cuál es la salida laboral de Periodismo y Nuevas Tecnologías?","respuesta":"La formación se vincula con medios, redacciones, áreas de prensa, agencias de contenidos y proyectos de comunicación digital. Permite participar en redacción multimedia, producción audiovisual y gestión de contenidos para redes sociales."}]}]';
